+36|  // FNV-1a hash for stable pseudo-randomness.
+37|  function stableHash(str) {
+38|    let h = 2166136261;
+39|    for (let i = 0; i < str.length; i += 1) {
+40|      h ^= str.charCodeAt(i);
+41|      h = Math.imul(h, 16777619);
+42|    }
+43|    return h >>> 0;
+44|  }
