+180|    merged.select('.col-name').text((d) => d.fullName);
+181|    merged.select('.col-sector').text((d) => d.sector);
+182|    merged.select('.col-mc').text((d) => formatMarketCap(d.marketCap));
+183|
+184|    rows.exit().remove();
