+262|            `<div class="tt-title">${d.ticker}</div>` +
+263|            `<div class="tt-sub">${d.fullName}</div>` +
+264|            `<div class="tt-sub">Sector: ${d.sector}</div>` +
+265|            `<svg class="spark"></svg>`
+266|          )
+267|          .classed('visible', true)
+268|          .attr('aria-hidden', 'false');
+269|
